import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test19_executable';

function run(args) {
  const r = spawnSync(EXE, args, { encoding: 'utf8' });
  return { rc: r.status, out: r.stdout, err: r.stderr };
}

// Baseline: --b 'TPc' -> line2 == b'\x01Z\xc7'
const BASE = "b'\\x01Z\\xc7'";

// Candidate trailing characters: full Unicode whitespace-ish sweep + controls
const codes = [];
for (let i = 0; i <= 0x20; i++) codes.push(i);
codes.push(0x7f, 0x85, 0xa0, 0x1680, 0x180e, 0x2000, 0x2001, 0x2002, 0x2003,
  0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x200b,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0xfeff);

const stripped = [];
const kept = [];
for (const cp of codes) {
  if (cp === 0) continue; // cannot pass NUL through argv
  const ch = String.fromCodePoint(cp);
  const { rc, out } = run(['--a', 'x', '--b', 'TPc' + ch, '--c', 'x', '--d', 'x', '--e', '1', '--f', '1']);
  const line2 = rc === 0 ? out.split('\n')[1] : null;
  if (line2 === BASE) stripped.push(cp); else kept.push(cp);
}
const hex = (a) => a.map((c) => 'U+' + c.toString(16).padStart(4, '0').toUpperCase()).join(' ');
console.log('STRIPPED:', hex(stripped));
console.log('KEPT    :', hex(kept));

