import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test19_executable';
const base = { a: 'x', b: '', c: 'x', d: 'x', e: '1', f: '1' };
function run(over) {
  const m = { ...base, ...over };
  const args = [];
  for (const k of ['a', 'b', 'c', 'd', 'e', 'f']) args.push('--' + k, m[k]);
  const r = spawnSync(EXE, args, { encoding: 'utf8' });
  return { rc: r.status, out: r.stdout, err: r.stderr };
}
const cases = {
  'a: lone surrogate (invalid utf8 argv)': { a: '\udcff' },
  'c: lone surrogate': { c: '\udcff' },
  'd: lone surrogate': { d: '\udcff' },
  'b: non-ascii (unicode encode err)': { b: '中' },
  'b: invalid b58 char': { b: '0' },
  'b: invalid b58 char l': { b: 'abcl' },
  'b: quote char err': { b: "'" },
  'b: backslash err': { b: '\\' },
  'b: non-ascii after valid': { b: 'TPéc' },
};
for (const [name, over] of Object.entries(cases)) {
  const { rc, out, err } = run(over);
  console.log('===== ' + name + '  rc=' + rc);
  console.log('STDOUT:' + JSON.stringify(out));
  console.log('STDERR:\n' + err);
}

