import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test19_executable';
// Pass raw, invalid-UTF-8 bytes through bash $'' quoting to trigger surrogateescape.
function raw(which, byteseq) {
  const parts = { a: 'x', b: '', c: 'x', d: 'x', e: '1', f: '1' };
  const args = ['a', 'b', 'c', 'd', 'e', 'f'].map((k) =>
    k === which ? `--${k} $'${byteseq}'` : `--${k} '${parts[k]}'`
  ).join(' ');
  const r = spawnSync('/bin/bash', ['-c', `${EXE} ${args}`], { encoding: 'utf8' });
  return { rc: r.status, out: r.stdout, err: r.stderr };
}
for (const w of ['a', 'b', 'c', 'd']) {
  const { rc, out, err } = raw(w, '\\xff');
  console.log(`===== --${w} = raw 0xFF   rc=${rc}`);
  console.log('STDOUT:' + JSON.stringify(out));
  console.log('STDERR:\n' + err);
}
// Two invalid bytes mid-string, to check the reported position index.
const r2 = raw('a', 'ab\\xff\\xfe');
console.log('===== --a = ab\\xff\\xfe  rc=' + r2.rc + '\nSTDERR:\n' + r2.err);
// Valid latin1-ish multibyte in --d (no error expected) for the repr path.
const r3 = raw('d', '\\xc3\\xa9');
console.log('===== --d = \\xc3\\xa9  rc=' + r3.rc + '\nSTDOUT:' + JSON.stringify(r3.out));

