cd /tmp && node --input-type=module -e "
import { createHash } from 'node:crypto';
const AL='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function enc(bytes){let z=0;while(z<bytes.length&&bytes[z]===0)z++;let acc=0n;for(const b of bytes.slice(z))acc=acc*256n+BigInt(b);let s='';while(acc>0n){s=AL[Number(acc%58n)]+s;acc/=58n;}return AL[0].repeat(z)+s;}
function dsha(bytes){const h1=createHash('sha256').update(Uint8Array.from(bytes)).digest();const h2=createHash('sha256').update(h1).digest();return [...h2];}
function encCheck(bytes){return enc([...bytes,...dsha(bytes).slice(0,4)]);}
const u=s=>[...new TextEncoder().encode(s)];
const cases=[['x','EYVuQ4z'],['','3QJmnh'],['drn1vtp','RugdwT5LcHrzv1F'],['U5Oa2ji3Q','86dtL4CqsHrKvLU76g'],['TPcTsjvTNHtabUBA','2B8Ua3UeB29D1HAoBVBUQubtw2de'],[\"a\\\"b'c\",'2EiE4wnFjMVTa']];
for(const [inp,exp] of cases){const got=encCheck(u(inp));console.log((got===exp?'OK  ':'FAIL')+'  '+JSON.stringify(inp)+' -> '+got+(got===exp?'':' expected '+exp));}
// also verify encoded_check_decoded for --b '5Q' -> decoded b'\xff' -> expect VrZDWwe
console.log((encCheck([0xff])==='VrZDWwe'?'OK  ':'FAIL')+'  [0xff] -> '+encCheck([0xff]));
console.log((enc(u('中国汉字'))==='5KLbY4YtwK7rEVHY2'?'OK  ':'FAIL')+'  b58encode(中国汉字) -> '+enc(u('中国汉字')));
"

