// Independent differential fuzzer: /output/test19.mjs  vs  the reference binary.
// (This is a throwaway probe tool in /tmp, not part of the deliverable, so it is free
// to use whatever Node APIs it likes.)
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test19_executable';
const PORT = ['/output/test19.mjs'];
const TIMEOUT = 15000;

let seed = 0x2f6e2b1;
function rnd() { seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5; seed >>>= 0; return seed / 4294967296; }
const pick = (a) => a[Math.floor(rnd() * a.length)];
const int = (n) => Math.floor(rnd() * n);

const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const NOTB58 = '0OIl+/=!@#$%^&*()[]{}<>,.?;:~`|\\\'"-_';
const WS = ['	', '
', '', ' ', '', '', '', '',
  '', ' ', '', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', '　'];
const NONWS = ['᠎', '​', '﻿', '', '', ''];
const UNI = ['中', '国', 'é', 'ü', '😀', '🎉', '𝔘', 'ß', 'Ω', 'א', 'ก', '́', 'ﬁ', '　'];

function rstr(kind) {
  const n = int(12) + 1;
  switch (kind) {
    case 'b58': { let s = ''; for (let i = 0; i < n; i++) s += pick([...B58]); return s; }
    case 'b58long': { let s = ''; for (let i = 0; i < 300 + int(700); i++) s += pick([...B58]); return s; }
    case 'ones': return '1'.repeat(int(2000)) + (rnd() < 0.5 ? rstr('b58') : '');
    case 'bad': { let s = ''; for (let i = 0; i < n; i++) s += rnd() < 0.3 ? pick([...NOTB58]) : pick([...B58]); return s; }
    case 'ws': return pick(WS).repeat(int(3) + 1) + rstr('b58') + pick(WS).repeat(int(3) + 1);
    case 'wstrail': return rstr('b58') + pick(WS).repeat(int(4) + 1);
    case 'wsonly': { let s = ''; for (let i = 0; i < n; i++) s += pick(WS); return s; }
    case 'nonws': return rstr('b58') + pick(NONWS);
    case 'uni': { let s = ''; for (let i = 0; i < n; i++) s += rnd() < 0.5 ? pick(UNI) : pick([...B58]); return s; }
    case 'quote': { let s = ''; for (let i = 0; i < n; i++) s += pick(['\'', '"', '\\', 'a', ' ', '\t']); return s; }
    case 'ascii': { let s = ''; for (let i = 0; i < n; i++) s += String.fromCharCode(32 + int(95)); return s; }
    case 'empty': return '';
    case 'huge': { let s = ''; for (let i = 0; i < 1500; i++) s += String.fromCharCode(32 + int(95)); return s; }
    default: return 'x';
  }
}
const STRKINDS = ['b58', 'b58long', 'ones', 'bad', 'ws', 'wstrail', 'wsonly', 'nonws',
  'uni', 'quote', 'ascii', 'empty', 'huge'];

const INTS = ['0', '1', '2', '57', '58', '59', '3363', '3364', '18446744073709551616',
  '115792089237316195423570985008687907853269984665640564039457584007913129639936',
  '1' + '0'.repeat(60), '473379435', '+7', ' 42 ', '\t42\n', ' 42', '　42',
  '1_0', '1_000_000', '١٠', '१०', '４２', '0x10', '3.5', '', '1__0', '_10', '10_', '- 5',
  '²', '-0', '999999999999999999999999999999'];

function norm(s) { return s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI:ERROR]'); }
function run(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], { encoding: 'latin1', timeout: TIMEOUT });
  return { rc: r.status, out: r.stdout ?? '', err: norm(r.stderr ?? '') };
}

const cases = [];
// 1. The four documented sample cases.
cases.push(['--a', 'c0C zQokldyRqDWOdqXxM2Eq4GyQ4sPmlsbgl', '--b', '     ', '--c', 'drn1vtp', '--d', 'drn1vtp', '--e', '473379435', '--f', '82019528']);
cases.push(['--a', '1234567890', '--b', '2Qu1ga2eTaoXNQzeniuzRQxH1rnQ', '--c', 'TPcTsjvTNHtabUBA', '--d', 'U5Oa2ji3Q', '--e', '10', '--f', '670280744']);
cases.push(['--a', '     ', '--b', 'TPcTsjvTNHtabUBA', '--c', 'U5Oa2ji3Q', '--d', '     ', '--e', '100', '--f', '151947396']);
cases.push(['--a', 'U5Oa2ji3Q', '--b', '2Qu1ga2eTaoXNQzeniuzRQxH1rnQ', '--c', 'c0C zQokldyRqDWOdqXxM2Eq4GyQ4sPmlsbgl', '--d', '中国汉字', '--e', '10', '--f', '262631383']);
// 2. Hand-picked vectors.
const V = [['x', '', 'x', 'x', '0', '1'], ['', '', '', '', '0', '0'], ['x', '111TPc', 'x', 'x', '1', '1'],
  ['x', 'TPc   ', 'x', 'x', '1', '1'], ['x', '1  ', 'x', 'x', '1', '1'], ['x', '11 ', 'x', 'x', '1', '1'],
  ['x', '5Q', 'x', 'x', '1', '1'], ['it\'s', '', 'a"b\'c', '\'', '1', '1'],
  ['😀é中', '', '😀', '😀é', '1', '1'], ['x', '', 'x', 'x', '1' + '0'.repeat(59), '1']];
for (const v of V) cases.push(['--a', v[0], '--b', v[1], '--c', v[2], '--d', v[3], '--e', v[4], '--f', v[5]]);
// 3. Every single trailing whitespace / non-whitespace codepoint on --b.
for (const ch of [...WS, ...NONWS]) cases.push(['--a', 'x', '--b', 'TPc' + ch, '--c', 'x', '--d', 'x', '--e', '1', '--f', '1']);
// 4. Every integer form on --e and on --f.
for (const iv of INTS) {
  cases.push(['--a', 'x', '--b', '', '--c', 'x', '--d', 'x', '--e', iv, '--f', '1']);
  cases.push(['--a', 'x', '--b', '', '--c', 'x', '--d', 'x', '--e', '1', '--f', iv]);
}
// 5. Every byte 0x00-0xff round-tripped through --d.
for (let b = 1; b < 256; b++) {
  const s = String.fromCharCode(b);
  cases.push(['--a', s, '--b', '', '--c', s, '--d', s, '--e', '1', '--f', '1']);
}
// 6. argparse failure modes.
const AP = [
  ['--a', 'x', '--b', '', '--c', 'x', '--d', 'x', '--e', '1'],
  ['--a', 'x', '--b', '', '--c', 'x', '--d', 'x'],
  [],
  ['--a', 'x'],
  ['--a', 'x', '--b', '', '--c', 'x', '--d', 'x', '--e', '1', '--f', '1', '--g', '2'],
  ['--a', 'x', '--b', '', '--c', 'x', '--d', 'x', '--e', '1', '--f'],
  ['--a=x', '--b=', '--c=x', '--d=x', '--e=1', '--f=1'],
  ['--a', 'x', '--a', 'y', '--b', '', '--c', 'x', '--d', 'x', '--e', '1', '--f', '1'],
  ['-h'],
  ['--help'],
  ['-a', 'x', '--b', '', '--c', 'x', '--d', 'x', '--e', '1', '--f', '1'],
  ['--a', 'x', '--b', '', '--c', 'x', '--d', 'x', '--e', '1', '--f', '1', 'extra'],
];
for (const c of AP) cases.push(c);
// 7. Randomized bulk.
const BULK = Number(process.argv[2] ?? 700);
for (let i = 0; i < BULK; i++) {
  cases.push(['--a', rstr(pick(STRKINDS)), '--b', rstr(pick(STRKINDS)), '--c', rstr(pick(STRKINDS)),
    '--d', rstr(pick(STRKINDS)), '--e', pick(INTS.filter((s) => !'-²'.includes(s[0]) && s !== '' && !s.includes('x') && !s.includes('.') && !s.includes('__') && s[s.length - 1] !== '_' && s[0] !== '_')),
    '--f', String(int(1e9))]);
}

let pass = 0; const fails = [];
for (const argv of cases) {
  const exp = run(EXE, [], argv);
  const got = run(process.execPath, PORT, argv);
  const stdoutOk = exp.out === got.out;
  const rcOk = exp.rc === got.rc;
  const stderrOk = exp.err === got.err;
  if (stdoutOk && rcOk && stderrOk) { pass++; continue; }
  fails.push({ argv, exp, got, stdoutOk, rcOk, stderrOk });
}
console.log(`total=${cases.length} pass=${pass} fail=${fails.length}`);
const hard = fails.filter((f) => !f.stdoutOk || !f.rcOk);
console.log(`stdout/exitcode mismatches = ${hard.length}; stderr-only = ${fails.length - hard.length}`);
for (const f of fails.slice(0, 25)) {
  console.log('---- argv=' + JSON.stringify(f.argv));
  if (!f.rcOk) console.log('  rc: expected ' + f.exp.rc + ' got ' + f.got.rc);
  if (!f.stdoutOk) { console.log('  exp out: ' + JSON.stringify(f.exp.out)); console.log('  got out: ' + JSON.stringify(f.got.out)); }
  if (!f.stderrOk) { console.log('  exp err: ' + JSON.stringify(f.exp.err)); console.log('  got err: ' + JSON.stringify(f.got.err)); }
}
process.exit(hard.length ? 1 : 0);

